pub fn format_cpp_float(value: f32) -> String {
    if value.is_nan() {
        return String::from("nan");
    }

    if value.is_infinite() {
        return if value.is_sign_negative() {
            String::from("-inf")
        } else {
            String::from("inf")
        };
    }

    if value == 0.0_f32 {
        return if value.is_sign_negative() {
            String::from("-0")
        } else {
            String::from("0")
        };
    }

    let sign = if value.is_sign_negative() { "-" } else { "" };
    let absolute = value.abs();
    let rounded_scientific = format!("{absolute:.5e}");
    let (mantissa, exponent) = rounded_scientific
        .split_once('e')
        .expect("scientific formatting must include an exponent");
    let exponent_value = exponent
        .parse::<i32>()
        .expect("formatted exponent must parse as an integer");

    if exponent_value < -4 || exponent_value >= 6 {
        let trimmed_mantissa = trim_fractional_zeros(mantissa);
        return format!("{sign}{trimmed_mantissa}e{exponent_value:+03}");
    }

    let precision = (6_i32 - (exponent_value + 1)).max(0) as usize;
    let fixed = format!("{absolute:.precision$}");
    let trimmed = trim_fractional_zeros(&fixed);
    format!("{sign}{trimmed}")
}

fn trim_fractional_zeros(raw: &str) -> String {
    if !raw.contains('.') {
        return raw.to_string();
    }

    let trimmed = raw.trim_end_matches('0').trim_end_matches('.');
    if trimmed.is_empty() {
        String::from("0")
    } else {
        trimmed.to_string()
    }
}

