mod color;

use color::{format_cpp_float, ColorConverter, RGB};
use std::env;
use std::io::{self, Write};

fn main() {
    let args: Vec<String> = env::args().collect();
    let (mut r, mut g, mut b) = (0.3_f32, 0.7_f32, 0.2_f32);

    if args.len() > 3 {
        r = parse_arg(&args[1]);
        g = parse_arg(&args[2]);
        b = parse_arg(&args[3]);
    }

    let rgb = RGB::new(r, g, b);
    let inverted = ColorConverter::invert(rgb);
    let grayscale = ColorConverter::grayscale(rgb);

    println!(
        "{} {} {} {} {} {}",
        format_cpp_float(inverted.r),
        format_cpp_float(inverted.g),
        format_cpp_float(inverted.b),
        format_cpp_float(grayscale.r),
        format_cpp_float(grayscale.g),
        format_cpp_float(grayscale.b)
    );
}

fn parse_arg(input: &str) -> f32 {
    input.parse::<f32>().unwrap_or_else(|_| abort_stof())
}

fn abort_stof() -> ! {
    let mut stderr = io::stderr().lock();
    let _ = writeln!(
        stderr,
        "terminate called after throwing an instance of 'std::invalid_argument'"
    );
    let _ = writeln!(stderr, "  what():  stof");
    let _ = stderr.flush();
    std::process::abort();
}

